import type { HTTPError } from "../../error.ts";

export const problemContentType = "application/problem+json;charset=UTF-8";

export function problemBody(error: HTTPError, debug?: boolean): Record<string, unknown> {
  const { status, statusText, unhandled } = error;
  const defaultText = statusTexts[status];
  const stack = debug && error.stack ? error.stack.split("\n").map((l) => l.trim()) : undefined;

  if (unhandled) {
    return {
      type: error.type ?? "about:blank",
      title: defaultText ?? "Error",
      status,
      instance: error.instance,
      stack,
    };
  }

  const message = error.message;
  const generic =
    !message ||
    message === statusText ||
    message === defaultText ||
    message === ["HTTPError", status, statusText].filter(Boolean).join(" ");

  return {
    ...(error.data === undefined ? undefined : { data: error.data }),
    ...error.body,
    type: error.type ?? "about:blank",
    title: statusText ?? defaultText ?? "Error",
    status,
    detail: generic ? undefined : message,
    instance: error.instance,
    stack,
